///  <span class="type">int</span> x <span class="operator">=</span> v<span class="operator">.</span>toInt();              <span class="comment">// x = 123</span>
///  out <span class="operator">&lt;</span><span class="operator">&lt;</span> v;                       <span class="comment">// Writes a type tag and an int to out</span>
///  v <span class="operator">=</span> <span class="type"><a href="http://doc.qt.io/qt-5/qvariant.html" translate="no">QVariant</a></span>(tr(<span class="string">"hello"</span>));      <span class="comment">// The variant now contains a QString</span>
///  <span class="type">int</span> y <span class="operator">=</span> v<span class="operator">.</span>toInt();              <span class="comment">// y = 0 since v cannot be converted to an int</span>
///  <span class="type"><a href="http://doc.qt.io/qt-5/qstring.html" translate="no">QString</a></span> s <span class="operator">=</span> v<span class="operator">.</span>toString();       <span class="comment">// s = tr("hello")  (see QObject::tr())</span>
